#ifndef AUSSOM_STDLIB_UNICODE_H
#define AUSSOM_STDLIB_UNICODE_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/* java.lang.String operations on UTF-16 code units, as the string
 * methods need them. The case and digit tables were generated by
 * running the JDK 23 runtime (en_US locale) over every code point. The
 * comparison rules, and the word boundaries toLower's final sigma
 * depends on, were learned from its results on random input (see
 * unicode.c). No JDK source was used. The tables are Unicode Character
 * Database 15.1.0 data, under the Unicode License V3 (Copyright
 * 1991-2024 Unicode, Inc.); the full notice is in THIRD-PARTY.md. */

/* String.compareTo: the difference of the first differing units, else
 * the difference of the lengths. */
int64_t uni_compare(const uint16_t *a, size_t na, const uint16_t *b, size_t nb);

/* String.compareToIgnoreCase and String.equalsIgnoreCase. */
int64_t uni_compare_icase(const uint16_t *a, size_t na, const uint16_t *b, size_t nb);
bool uni_equals_icase(const uint16_t *a, size_t na, const uint16_t *b, size_t nb);

/* String.toUpperCase() and String.toLowerCase(). The result is
 * GC-allocated; its length goes to *out_n. */
uint16_t *uni_to_upper(const uint16_t *s, size_t n, size_t *out_n);
uint16_t *uni_to_lower(const uint16_t *s, size_t n, size_t *out_n);

/* Character.digit(c, 10) for a character Character.isDigit accepts:
 * 0 to 9, or -1. */
int uni_digit(uint32_t cp);

/* String.indexOf(needle, from) and String.lastIndexOf(needle, from),
 * with Java's clamping of `from`. */
int64_t uni_index_of(const uint16_t *s, size_t n, const uint16_t *needle, size_t nn, int64_t from);
int64_t uni_last_index_of(const uint16_t *s, size_t n, const uint16_t *needle, size_t nn, int64_t from);

#endif /* AUSSOM_STDLIB_UNICODE_H */
